(function(){const urlParams=new URLSearchParams(window.location.search),referrer=document.referrer,storageKey='traffic_info',maxAgeMs=30*24*60*60*1e3,now=Date.now(),paidMediums=['cpc','ppc','paid','ads'],socialDomains=['facebook.','instagram.','tiktok.','linkedin.','twitter.','pinterest.'];function hasTrackingConsent(){const c=document.cookie.split('; ').find(r=>r.startsWith('patlis-cookie='));if(!c)return false;try{const v=JSON.parse(decodeURIComponent(c.split('=').slice(1).join('=')));return!!(v.statistics||v.marketing||v.all)}catch(e){return false}}const gclid=urlParams.get('gclid')||'',gbraid=urlParams.get('gbraid')||'',wbraid=urlParams.get('wbraid')||'',msclkid=urlParams.get('msclkid')||'',fbclid=urlParams.get('fbclid')||'';let s={utm_source:'',utm_medium:'',utm_campaign:'',referrer:referrer||'',landing_page:window.location.pathname,created_at:now,gclid,gbraid,wbraid,msclkid,fbclid};if(urlParams.has('utm_source')){s.utm_source=urlParams.get('utm_source');s.utm_medium=urlParams.get('utm_medium')||'';s.utm_campaign=urlParams.get('utm_campaign')||''}else if(referrer){const rh=new URL(referrer).hostname,ch=window.location.hostname;if(rh===ch){s.utm_source='(direct)';s.utm_medium='(none)';s.referrer=''}else if(rh.includes('google.')){s.utm_source='google';s.utm_medium='organic'}else if(rh.includes('bing.')){s.utm_source='bing';s.utm_medium='organic'}else if(socialDomains.some(d=>rh.includes(d))){s.utm_source=rh;s.utm_medium='social'}else{s.utm_source=referrer;s.utm_medium='referral'}}else{s.utm_source='(direct)';s.utm_medium='(none)';s.referrer=''}if(hasTrackingConsent()){let vid=localStorage.getItem('patlis_vid');if(!vid){vid=crypto.randomUUID();localStorage.setItem('patlis_vid',vid)}const stored=localStorage.getItem(storageKey);if(!stored){localStorage.setItem(storageKey,JSON.stringify(s))}else{try{const d=JSON.parse(stored),age=now-d.created_at,expired=!d.created_at||age>maxAgeMs,newAds=!!(s.gclid||s.gbraid||s.wbraid||s.msclkid||s.fbclid),paidUtm=paidMediums.includes((s.utm_medium||'').toLowerCase());if(expired||newAds||paidUtm){if(!s.gclid&&d.gclid)s.gclid=d.gclid;if(!s.gbraid&&d.gbraid)s.gbraid=d.gbraid;if(!s.wbraid&&d.wbraid)s.wbraid=d.wbraid;if(!s.msclkid&&d.msclkid)s.msclkid=d.msclkid;if(!s.fbclid&&d.fbclid)s.fbclid=d.fbclid;localStorage.setItem(storageKey,JSON.stringify(s))}}catch(e){localStorage.setItem(storageKey,JSON.stringify(s))}}}const raw=localStorage.getItem(storageKey);if(!raw)return;let td;try{td=JSON.parse(raw)}catch(e){localStorage.removeItem(storageKey);return}if(!td.created_at||now-td.created_at>maxAgeMs){localStorage.removeItem(storageKey);return}td.visitor_id=localStorage.getItem('patlis_vid')||'';const fields=document.querySelectorAll('[name="traffic_info"]');if(!fields.length)return;fields.forEach(f=>{f.value=JSON.stringify(td)});document.querySelectorAll('[name="source_url"]').forEach(f=>{f.value=window.location.pathname+window.location.search});const pll=document.cookie.split('; ').find(r=>r.startsWith('pll_language='));document.querySelectorAll('[name="language"]').forEach(f=>{f.value=pll?pll.split('=')[1]:''});const ua=navigator.userAgent,dt=/Mobi|Android|iPhone|iPod/.test(ua)&&!/iPad/.test(ua)?'mobile':/iPad|Tablet|PlayBook|Silk/.test(ua)||(/Android/.test(ua)&&!/Mobile/.test(ua))?'tablet':'desktop';document.querySelectorAll('[name="device_type"]').forEach(f=>{f.value=dt})})();
